const webhookData = $input.first();
const body = webhookData.json.body || {};

// Ambil data dari Kirimi
const userMessage = body.message || "";
const messageType = body.messageType || "";
const userNumber = body.from || "unknown";  // ← TIDAK strip @lid, passthrough as-is
const _isLid    = String(userNumber).toLowerCase().includes('@lid');
const userLid   = String(body.originLid || (_isLid ? userNumber : '')).replace(/\D/g, '');// kunci cocok
const userPhone = _isLid ? '' : String(userNumber).replace(/\D/g, '');// utk kolom No WA
const userName = body.name || body.pushName || body.notifyName || "User";
const isFromMe = body.isFromMe === true;
const eventType = body.event || "";

// Filter: hanya pesan teks yang tidak kosong
if (messageType !== "text" || !userMessage || userMessage.trim() === "") {
    console.log('⛔ STOP: Bukan pesan teks valid');
    return [];
}

console.log('✅ LANJUT: Pesan teks valid dari user');
console.log('📱 No WA:', userNumber);

// Counter sederhana
let counter = $vars.chatCounter || 0;
counter++;
$vars.chatCounter = counter;

// Format tanggal & jam WIB
const now = new Date();
const formattedDate = now.toLocaleDateString('en-GB', {
    timeZone: 'Asia/Jakarta',
    day: '2-digit',
    month: '2-digit',
    year: 'numeric'
});
const formattedTime = now.toLocaleTimeString('id-ID', {
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: false,
    timeZone: 'Asia/Jakarta'
}).replace(/\./g, ':');

const processStartTs = Date.now();

const aiInputText = `[SYSTEM_DATA]
CHAT_COUNTER: ${counter}
USER_NAME: ${userName}
USER_MESSAGE: "${userMessage}"

[USER QUERY]
${userMessage}`;

return [{
    json: {
        chat_counter: counter,
        user_wa: userNumber,
        user_lid: userLid,
        user_phone: userPhone,
        user_name: userName,
        formatted_date: formattedDate,
        formatted_time: formattedTime,
        ai_input_text: aiInputText,
        original_message: userMessage,
        body: body,
        message_type: messageType,
        process_start_ts: processStartTs
    }
}];

// ====================================================================
// FINAL FIX: Handle empty strings dengan || operator
// ====================================================================

const debugLog = [];

try {
    const allItems = $input.all();
    debugLog.push("Step 1: Received " + allItems.length + " items from Read STATS");

    // ====================================================================
    // Ambil data dari Chat Counter
    // ====================================================================
    const chatCounterNode = $('Chat Counter').first();
    if (!chatCounterNode) {
        throw new Error("Chat Counter node not found!");
    }

    const chatCounter = chatCounterNode.json;
    if (!chatCounter) {
        throw new Error("Chat Counter json is empty!");
    }

    const searchNoWA = chatCounter.user_phone;   // nomor HP utk kolom No WA
    const searchLid  = chatCounter.user_lid;      // LID utk pencocokan
    const userName = chatCounter.user_name || "User";
    const userMessage = chatCounter.original_message || "";

    debugLog.push("Step 2: Chat Counter data OK");
    debugLog.push("  - No WA: " + searchNoWA);
    debugLog.push("  - Nama: " + userName);
    debugLog.push("  - Pesan: " + userMessage);

    if (!searchLid) {
        throw new Error("user_lid is missing!");
    }

    // ====================================================================
    // Process sheet rows
    // ====================================================================
    const sheetRows = allItems
        .filter(item => {
            const data = item?.json || item;
            if (!data || Object.keys(data).length === 0) {
                return false;
            }
            return !!(data['lid'] || data['No WA'] || data.no_wa || data.NoWA);
        })
        .map(item => item?.json || item);

    debugLog.push("Step 3: Sheet rows found: " + sheetRows.length);

    // ====================================================================
    // Find existing row
    // ====================================================================
    const searchLidStr = String(searchLid);
    const existingRow = sheetRows.find(row => {
        const rowLid = row['lid'] ?? row.LID;
        return rowLid && rowLid.toString() === searchLidStr;
    });

    const isNewUser = !existingRow;
    debugLog.push("Step 4: User status = " + (isNewUser ? "NEW USER" : "EXISTING USER"));

    // ====================================================================
    // Calculate values - FIXED: Pakai || untuk handle empty strings
    // ====================================================================
    let counter, pesanPertama, tanggalPertama, intensitasChat;

    if (existingRow) {
        // User sudah ada
        debugLog.push("Step 5a: Existing user - raw values:");
        debugLog.push("  - existingRow.Counter = '" + existingRow.Counter + "' (type: " + typeof existingRow.Counter + ")");
        debugLog.push("  - existingRow['Pesan Pertama'] = '" + existingRow['Pesan Pertama'] + "' (type: " + typeof existingRow['Pesan Pertama'] + ")");

        // FIX: Pakai || untuk handle empty string, bukan ??
        counter = parseInt(existingRow.Counter || existingRow.counter || 0) + 1;
        intensitasChat = parseInt(existingRow['Intensitas Chat'] || existingRow.intensitas_chat || 0) + 1;

        // FIX: Pakai || dan trim check untuk handle empty string
        const pesanLama = existingRow['Pesan Pertama'] || existingRow.pesan_pertama;
        pesanPertama = (pesanLama && pesanLama.trim() !== '') ? pesanLama : userMessage;

        tanggalPertama = existingRow.Tanggal || existingRow.tanggal || null;

        debugLog.push("Step 5b: Existing user processed");
        debugLog.push("  - Counter: " + counter);
        debugLog.push("  - Intensitas: " + intensitasChat);
        debugLog.push("  - Pesan Pertama: '" + pesanPertama + "'");
    } else {
        // User baru
        counter = 1;
        intensitasChat = 1;
        pesanPertama = userMessage;
        tanggalPertama = null;

        debugLog.push("Step 5: New user processed");
        debugLog.push("  - Counter: " + counter);
        debugLog.push("  - Intensitas: " + intensitasChat);
        debugLog.push("  - Pesan Pertama: '" + pesanPertama + "'");
    }

    // Verify
    debugLog.push("Step 6: Pre-return verification:");
    debugLog.push("  - counter value: " + counter + " (type: " + typeof counter + ")");
    debugLog.push("  - pesanPertama value: '" + pesanPertama + "' (length: " + pesanPertama.length + ")");

    // ====================================================================
    // Set tanggal
    // ====================================================================
    if (!tanggalPertama) {
        const now = new Date();
        tanggalPertama = now.toLocaleDateString('en-GB', {
            timeZone: 'Asia/Jakarta',
            day: '2-digit',
            month: '2-digit',
            year: 'numeric'
        });
    }

    const jamWIB = new Date().toLocaleTimeString('id-ID', {
        hour: '2-digit',
        minute: '2-digit',
        hour12: false,
        timeZone: 'Asia/Jakarta'
    }).replace('.', ':');

    // ====================================================================
    // Build output
    // ====================================================================
    const outputData = {
        "No WA": searchNoWA,
        "lid": searchLid,
        "Tanggal": tanggalPertama,
        "TanggalSekarang": new Date().toLocaleDateString('en-GB', {  // ← TAMBAH INI
            timeZone: 'Asia/Jakarta',
            day: '2-digit',
            month: '2-digit',
            year: 'numeric'
        }),
        "Jam": jamWIB,
        "Nama": userName,
        "Pesan Pertama": pesanPertama,
        "Counter": counter,
        "Intensitas Chat": intensitasChat,
        "Last Timestamp": chatCounter.webhook_timestamp || Math.floor(Date.now()/1000),

        // DEBUG INFO - bisa hapus nanti kalau udah oke
        "_DEBUG": {
            "logs": debugLog,
            "isNewUser": isNewUser,
            "sheetRowsCount": sheetRows.length
        }
    };

    return [{
        json: outputData
    }];

} catch (error) {
    debugLog.push("ERROR: " + error.message);

    return [{
        json: {
            "No WA": "ERROR",
            "Counter": null,
            "Pesan Pertama": "",
            "Intensitas Chat": null,
            "_DEBUG": {
                "error": error.message,
                "logs": debugLog
            }
        }
    }];
}

const chatCounter = $('Chat Counter').first().json;

// DATA LANGSUNG DARI CHAT COUNTER NODE
const userNumber = chatCounter.user_wa;
const userName = chatCounter.user_name;
const userMessage = chatCounter.original_message;   // ← perbaikan utama

// VALIDASI SEDERHANA
if (!userNumber) {
  throw new Error("user_wa tidak ditemukan di input!");
}

console.log("✅ Data berhasil di-extract:");
console.log("- No WA:", userNumber);
console.log("- Nama:", userName);
console.log("- Pesan:", userMessage);

return [{
  json: {
    search_no_wa: userNumber,
    user_name: userName,
    user_message: userMessage,
    timestamp: chatCounter.formatted_date + ' ' + chatCounter.formatted_time + ' WIB',
    source: "chat_counter_node",
    is_valid: userNumber !== "unknown"
  }
}];

// Cek apakah Kirimi API sukses
const input = $input.first();
const responseData = input.json;

// Kirimi API return success jika ada field 'status' = true atau 'data'
const isSuccess = responseData.status === true || 
                  responseData.success === true ||
                  (responseData.data && responseData.data.id) ||
                  (responseData.message && responseData.message !== 'error');

if (!isSuccess) {
  console.log('❌ Kirimi API Response Error:', JSON.stringify(responseData));
  throw new Error('Kirimi API gagal: ' + JSON.stringify(responseData));
}

console.log('✅ Kirimi API sukses:', JSON.stringify(responseData));
return [input];

// ============================================================
// HUMAN-IN-THE-LOOP CHECK
// Baca kolom 'bot_mode' dari STATS sheet untuk user ini.
// Jika bot_mode = 'OFF' → Sam sedang handle manual → stop, jangan reply.
// Jika kosong / 'ON' / apapun selain 'OFF' → bot aktif, lanjut.
// ============================================================

const cc = $('Chat Counter').first().json;
const userWa = cc.user_wa;
const userLid = cc.user_lid;

// Ambil data STATS dari node Read STATS (dijalankan sebelum node ini)
// Node Read STATS membaca seluruh sheet, kita filter by No WA
const statsRows = $('Read STATS for HITL').all();
const userRow = statsRows.find(r => {
  const lid = String(r.json['lid'] || '').trim();
  return lid === String(userLid).trim();
});

const botMode = userRow ? String(userRow.json['bot_mode'] || '').trim().toUpperCase() : '';

if (botMode === 'OFF') {
  console.log(`👨‍💼 HITL AKTIF untuk ${userWa} — Sam sedang handle manual, bot berhenti.`);
  return [];
}

console.log(`🤖 Bot mode AKTIF untuk ${userWa} (bot_mode="${botMode}") — lanjut ke AI.`);
return [$input.first()];

// ====================================================================
// NODE: Cek_user_status
// Type: Code (JavaScript)
// ====================================================================

const chatCounter = $('Chat Counter').first().json;
const statsRows = $('Read User STATS').all();
const userWa  = chatCounter.user_wa;
const userLid = chatCounter.user_lid;

// Cari user di STATS by LID (kunci stabil)
const userRow = statsRows.find(r => {
  const lid = String(r.json['lid'] || '').trim();
  return lid === String(userLid).trim();
});

const userStatus = userRow ? String(userRow.json['user_status'] || '').trim() : '';
const greetingSent = userRow ? String(userRow.json['greeting_sent'] || '').trim() : '';

// Ambil pending_msg dari Re-Read STATS Debounce — bukan Read User STATS
// Re-Read jalan SETELAH Wait 8 detik, jadi sudah punya semua bubble termasuk yang terakhir
const debounceRow = $('Re-Read STATS Debounce').first().json;
const botModeNow = String(debounceRow['bot_mode'] || '').trim().toUpperCase();
if (botModeNow === 'OFF') {
  console.log('👨‍💼 HITL (post-debounce): bot_mode OFF — berhenti, Sam handle manual.');
  return [];
}
const pendingMsg = (debounceRow['pending_msg'] || '').trim();
const userMessage = pendingMsg || chatCounter.original_message;

console.log(`📨 userMessage final ke AI:\n${userMessage}`);

// ============ SIMPLE BOOLEAN LOGIC ============
// Kirim greeting HANYA jika:
// 1. User belum punya status DAN
// 2. Greeting belum pernah dikirim (flag ≠ Y)
const counter = Number(userRow ? (userRow.json['Counter'] || 0) : 0) || 0;
const shouldAskStatus = (!userStatus && greetingSent !== 'Y' && counter <= 1);

if (shouldAskStatus) {
  console.log('🆕 New user - will send greeting');
} else if (userStatus) {
  console.log(`✅ User status: ${userStatus}`);
} else if (greetingSent === 'Y') {
  console.log('⛔ Greeting already sent - skip');
}

let aiSystemData = `[SYSTEM_DATA]
USER_WA: ${userWa}
USER_STATUS_IN_DB: ${userStatus || 'EMPTY'}
IS_NEW_USER: ${shouldAskStatus}
GREETING_SENT: ${greetingSent === 'Y' ? 'YES' : 'NO'}

CRITICAL INSTRUCTION:
${shouldAskStatus ? 
  `This is a NEW USER. You MUST ask: "${($('Parse Config').first().json.config||{}).status_question || 'Sebelumnya, boleh tahu yang sedang chat sekarang orang tua murid atau calon muridnya langsung?'}"` : 
  userStatus ? 
    `This user's status is: ${userStatus}. Use appropriate language.` :
    `Greeting already sent but user hasn't responded. Continue conversation naturally WITHOUT repeating the greeting.`
}

[USER QUERY]
${userMessage}`;

return [{
  json: {
    ...chatCounter,
    ai_input_text: aiSystemData,
    user_message_final: userMessage,
    user_status_from_db: userStatus,
    is_new_user: !userStatus,
    should_ask_status: shouldAskStatus
  }
}];

// ====================================================================
// UPDATE GREETING FLAG - ROBUST ALTERNATIVE
// ====================================================================
// This version uses pattern matching instead of exact keywords
// More flexible and covers any future variations

const processedData = $('Process All').first().json;
const cleanOutput = (processedData.cleanOutput || '').toLowerCase();
const shouldAskStatus = $('Cek_user_status').first().json.should_ask_status || false;
const chatCounter = $('Chat Counter').first().json;

// Check if output is asking about parent vs student
// Pattern: mentions both "orang tua" (or variants) AND "anak" (or variants) in question form
const hasParentReference = /orang\s*tua|ortu|bapak|ibu/.test(cleanOutput);
const hasStudentReference = /anak|murid|calon/.test(cleanOutput);
const isQuestion = /\?|ya\s*$/.test(cleanOutput); // Ends with ? or "ya"

const isStatusQuestion = hasParentReference && hasStudentReference && isQuestion;

// Alternative check: looks like first contact greeting
const hasGreeting = /halo|hai|terima kasih/.test(cleanOutput);
const isLikelyStatusQuestion = hasGreeting && isStatusQuestion;

// Update flag if this is status question
if (shouldAskStatus) {
  console.log(`📝 [GREETING SENT] Marking greeting_sent = Y for user ${chatCounter.user_wa}`);
  console.log(`📝 Detected status question pattern in: ${cleanOutput.substring(0, 100)}...`);
  console.log(`   Pattern matched: hasParent=${hasParentReference}, hasStudent=${hasStudentReference}, isQuestion=${isQuestion}`);

  return [{
    json: {
      user_wa: chatCounter.user_wa,
      user_lid: chatCounter.user_lid,
      greeting_sent: 'Y',
      update_needed: true
    }
  }];
} else {
  console.log('ℹ️ Not a status question');
  console.log(`   shouldAskStatus: ${shouldAskStatus}`);
  console.log(`   hasParentRef: ${hasParentReference}, hasStudentRef: ${hasStudentReference}, isQuestion: ${isQuestion}`);
  console.log(`   Output: ${cleanOutput.substring(0, 100)}`);

  return [{
    json: {
      update_needed: false
    }
  }];
}

