// Pilih link GForm dari sheet LINKS sesuai nama yang diminta AI (data-driven)
const rows = $('Query LINKS for GForm').all().map(i => i.json);
const proc = $('Process All').first().json;
const phone = $('Chat Counter').first().json.user_wa || proc.user_wa || '';
const requested = String(proc.gformLinkName || '').trim();

const norm = s => String(s || '').toLowerCase().replace(/\s+/g, ' ').trim();
const activeRows = rows.filter(r => /aktif|active|on|ya/i.test(String(r['Status'] || '')));

let match = null;
if (requested) {
  const rq = norm(requested);
  match = activeRows.find(r => norm(r['Nama Link']) === rq)
       || activeRows.find(r => { const n = norm(r['Nama Link']); return n && (n.includes(rq) || rq.includes(n)); });
}

if (match && match['URL']) {
  const desc = String(match['Deskripsi'] || '').trim();
  const intro = desc
    ? `Berikut ${desc.charAt(0).toLowerCase() + desc.slice(1)}`
    : `Berikut link ${match['Nama Link']}`;
  const message = `Haii! 😊 ${intro} ya:\n\n👉 ${match['URL']}\n\nSilakan diisi yaa, nanti tim kami follow up setelah form terisi. Ada yang mau ditanyain dulu sebelum isi? Santai aja tanya ke sini! 🙌`;
  console.log('✅ GForm link resolved:', match['Nama Link']);
  return [{ json: { ...proc, gformResolved: true, gformUrl: match['URL'], gformLinkName: match['Nama Link'], gformDesc: desc, phone, message } }];
}

// ── FALLBACK: nama kosong / tidak cocok -> tanya ulang link mana ──
const formRows = activeRows.filter(r => /gform|pendaftaran|mock/i.test(String(r['Nama Link'] || '')));
const listRows = formRows.length ? formRows : activeRows;
const opts = listRows.map(r => {
  const dsc = String(r['Deskripsi'] || '').trim();
  return dsc ? `• ${r['Nama Link']} (${dsc})` : `• ${r['Nama Link']}`;
}).join('\n');
const reason = requested ? `nama link "${requested}" tidak ketemu di LINKS` : 'AI tidak menyertakan nama link';
console.warn('⚠️ Pick GForm Link fallback (tanya ulang):', reason);
const message = opts
  ? `Boleh dibantu kirim link-nya 😊 Yang dimaksud yang mana ya:\n${opts}\n\nTinggal sebut salah satu, nanti langsung saya kirimkan.`
  : 'Boleh dibantu, link mana yang mau dikirim ya? Sebutkan program/keperluannya, nanti saya kirimkan.';
return [{ json: { ...proc, gformResolved: false, gformUrl: '', gformLinkName: requested, phone, message } }];

// Rate Limiter (ENGINE) — batas & window dari CONFIG (default 5/menit)
const cfg = $('Parse Config').first().json.config || {};
const userWa = $('Chat Counter').first().json.user_lid || $('Chat Counter').first().json.user_wa;
const now = Date.now();
const staticData = $getWorkflowStaticData('global');
const rateLimits = staticData.rateLimits || {};
const userKey = `rl_${userWa}`;
const windowMs = (Number(cfg.rate_limit_window_sec) || 60) * 1000;
const maxMessages = Number(cfg.rate_limit_max) || 5;
if (!rateLimits[userKey]) {
  rateLimits[userKey] = { count: 1, windowStart: now };
} else {
  const elapsed = now - rateLimits[userKey].windowStart;
  if (elapsed > windowMs) rateLimits[userKey] = { count: 1, windowStart: now };
  else rateLimits[userKey].count++;
}
staticData.rateLimits = rateLimits;
if (rateLimits[userKey].count > maxMessages) {
  console.log(`⛔ RATE LIMITED: ${userWa} (${rateLimits[userKey].count}/${maxMessages})`);
  return [];
}
console.log(`✅ RATE OK: ${userWa} pesan ke-${rateLimits[userKey].count}`);
return [$input.first()];

// ============================================================
// BOOTSTRAP CONFIG  (SATU-SATUNYA tempat edit per klien)
// Tempel Google Sheet ID milik klien di bawah ini. Semua config
// lain (persona, program, whitelist) ada di tab CONFIG sheet itu.
// ============================================================
const SHEET_ID = 'PASTE_CLIENT_GOOGLE_SHEET_ID_HERE';   // <-- EDIT INI per klien

const wh = $input.first() ? $input.first().json : {};
return [{ json: { ...wh, sheet_id: SHEET_ID } }];

// ============================================================
// PARSE CONFIG  (ENGINE — jangan edit per klien)
// Membaca tab CONFIG (kolom: key | value) jadi satu objek config.
// Nilai bertipe list/JSON ditulis sbg JSON string di sel value.
// Semua punya default aman -> kalau klien tidak isi, engine tetap jalan.
// ============================================================
const rows = $('Read CONFIG').all().map(i => i.json);
const sheetId = $('Bootstrap Config').first().json.sheet_id || '';

const raw = {};
for (const r of rows) {
  const k = String(r.key ?? r.Key ?? r.KEY ?? '').trim();
  if (!k) continue;
  raw[k] = (r.value ?? r.Value ?? r.VALUE ?? '');
}

const str = (k, def='') => {
  const v = raw[k];
  return (v === undefined || v === null || String(v).trim() === '') ? def : String(v).trim();
};
const num = (k, def) => { const raw = str(k, ''); if (raw === '') return def; const n = Number(raw); return Number.isFinite(n) ? n : def; };
const bool = (k, def=false) => { const v = str(k, '').toLowerCase(); if (v==='') return def; return ['true','yes','y','on','1','aktif','ya'].includes(v); };
const jsonArr = (k) => { try { const v = str(k,''); if (!v) return []; const p = JSON.parse(v); return Array.isArray(p) ? p : []; } catch(e){ return []; } };

const config = {
  sheet_id: sheetId,
  client_name: str('client_name', 'Client'),
  system_prompt: str('system_prompt', 'Kamu asisten AI yang ramah. Jawab hanya dari DATA TERVERIFIKASI & FAQ. Kalau tidak ada -> [UNKNOWN].'),
  status_question: str('status_question', 'Sebelumnya, boleh tahu yang sedang chat sekarang orang tua murid atau calon muridnya langsung?'),
  admin_phone: str('admin_phone', ''),
  bot_language: str('bot_language', 'id'),
  // whitelist
  whitelist_enabled: bool('whitelist_enabled', false),
  whitelist_numbers: jsonArr('whitelist_numbers').map(x => String(x).replace(/\D/g,'')),
  // rate limit & debounce
  rate_limit_max: num('rate_limit_max', 5),
  rate_limit_window_sec: num('rate_limit_window_sec', 60),
  debounce_seconds: num('debounce_seconds', 60),
  // NLU keyword lists (driver Preprocess) — semua opsional
  status_parent_keywords: jsonArr('status_parent_keywords'),
  status_student_keywords: jsonArr('status_student_keywords'),
  out_of_scope_keywords: jsonArr('out_of_scope_keywords'),
  register_keywords: jsonArr('register_keywords'),
  price_keywords: jsonArr('price_keywords'),
  batch_keywords: jsonArr('batch_keywords'),
  program_keywords: jsonArr('program_keywords'),
  grade_program_map: jsonArr('grade_program_map'), // [{keywords:[],grade,program,note}]
};

// pass-through input agar node berikutnya tetap punya body webhook
const passthrough = $('Bootstrap Config').first() ? $('Bootstrap Config').first().json : {};
return [{ json: { ...passthrough, config } }];

// ============================================================
// WHITELIST GATE  (ENGINE) — config-driven, anti-bug LID
// whitelist_enabled=false -> semua user lewat (mode produksi publik).
// whitelist_enabled=true  -> hanya nomor di whitelist_numbers (uji).
// Pencocokan tahan format: bandingkan digit dari `from` DAN `originLid`.
// ============================================================
const cfg = $('Parse Config').first().json.config || {};
const body = ($input.first().json.body) || ($('Parse Config').first().json.body) || {};

if (!cfg.whitelist_enabled) {
  return [$input.first()];
}

const list = (cfg.whitelist_numbers || []).map(x => String(x).replace(/\D/g, '')).filter(Boolean);
const fromDigits = String(body.from || '').replace(/\D/g, '');
const lidDigits  = String(body.originLid || '').replace(/\D/g, '');

const allowed = list.some(w => w && (w === fromDigits || w === lidDigits ||
  (fromDigits && fromDigits.endsWith(w)) || (w.endsWith(fromDigits) && fromDigits.length >= 6)));

if (!allowed) {
  console.log(`⛔ WHITELIST: ${fromDigits || lidDigits || 'unknown'} tidak di whitelist — stop.`);
  return [];
}
console.log(`✅ WHITELIST OK: ${fromDigits || lidDigits}`);
return [$input.first()];
